import sys

def checkMirrorTree(n, e, A, B):
    from collections import defaultdict

    def build_tree(edges):
        tree = defaultdict(list)
        for i in range(0, len(edges), 2):
            u, v = edges[i], edges[i + 1]
            tree[u].append(v)
        return tree

    treeA = build_tree(A)
    treeB = build_tree(B)

    def is_mirror(rootA, rootB):
        if rootA not in treeA and rootB not in treeB:
            return True
        if rootA not in treeA or rootB not in treeB:
            return False
        childrenA = treeA[rootA]
        childrenB = treeB[rootB]
        if len(childrenA) != len(childrenB):
            return False
        return all(is_mirror(a, b) for a, b in zip(childrenA, reversed(childrenB)))

    return 1 if is_mirror(1, 1) else 0

if __name__ == "__main__":
    input = sys.stdin.read().split()
    n = int(input[0])
    e = int(input[1])
    A = list(map(int, input[2:2+2*e]))
    B = list(map(int, input[2+2*e:]))
    print(checkMirrorTree(n, e, A, B))
